#nullable enable // autogenerated

using MVZ2Logic.Resources;
using PVZEngine;
using PVZEngine.Models;

namespace MVZ2.GameContent.Sprites
{
    public static class LogicSprites
    {
        public static SpriteReference GetModelIconReference(NamespaceID id, string type)
        {
            var modelID = id.ToModelID(type);
            var spriteID = new NamespaceID(modelID.SpaceName, $"model_icon/{modelID.Path}");
            return new SpriteReference(spriteID);
        }
    }
}
